namespace Sace.Api.Tests;

public class InvoiceCoveReconciliationV2Tests {
  [Fact] public void Single_candidate_without_evidence_is_never_confirmed(){var invoice=Doc("COMMERCIAL_INVOICE");var cove=Doc("COVE_ACK");var pair=Assert.Single(new InvoiceCovePairingService().Pair([invoice],[cove],[]));Assert.Equal(InvoiceCovePairingStatus.MANUAL_REVIEW,pair.Status);Assert.Equal(InvoiceCovePairingMethod.SINGLE_CANDIDATE,pair.Method);Assert.Equal("INSUFFICIENT_EVIDENCE",pair.ReasonCode);}

  [Fact] public void Exact_invoice_numbers_confirm_pairs_independently_of_input_order(){var a=Doc("COMMERCIAL_INVOICE","INV-A");var b=Doc("COMMERCIAL_INVOICE","INV-B");var coveB=Doc("COVE_ACK","INV-B");var coveA=Doc("COVE_ACK","INV-A");var pairs=new InvoiceCovePairingService().Pair([a,b],[coveB,coveA],[]);Assert.Equal(2,pairs.Count);Assert.All(pairs,x=>Assert.Equal(InvoiceCovePairingStatus.CONFIRMED,x.Status));Assert.All(pairs,x=>Assert.Equal(InvoiceCovePairingMethod.INVOICE_NUMBER_EXACT,x.Method));Assert.All(pairs,x=>Assert.Equal(x.Invoice!.Fields.Single().NormalizedValue,x.Cove!.Fields.Single().NormalizedValue));}

  [Fact] public void Confirmed_manual_relationship_is_auditable_pairing_evidence(){var invoice=Doc("COMMERCIAL_INVOICE");var cove=Doc("COVE_ACK");var relation=new DocumentRelationshipCandidate{SourceDocumentId=invoice.Id,TargetDocumentId=cove.Id,ReviewStatus=RelationshipReviewStatus.CONFIRMED,RelationshipType="INVOICE_COVE"};var pair=Assert.Single(new InvoiceCovePairingService().Pair([invoice],[cove],[relation]));Assert.Equal(InvoiceCovePairingStatus.CONFIRMED,pair.Status);Assert.Equal(InvoiceCovePairingMethod.MANUAL_CONFIRMATION,pair.Method);}

  [Fact] public void Line_matcher_never_pairs_by_row_description_quantity_or_unit(){var left=Item(1,null,"SAME",10,"PZA");var right=Item(1,null,"SAME",10,"PZA");var rows=new InvoiceCoveLineMatcher().Match([left],[right]);Assert.Contains(rows,x=>x.LeftLineItemId==left.Id&&x.Status==LineItemMatchStatus.NOT_COMPARABLE);Assert.DoesNotContain(rows,x=>x.Status==LineItemMatchStatus.MATCHED);}

  [Fact] public void Duplicate_explicit_identifiers_are_ambiguous_and_never_first(){var left=Item(1,"PART-1","A",10,"PZA");var rows=new InvoiceCoveLineMatcher().Match([left],[Item(7,"PART-1","B",1,"KG"),Item(2,"PART-1","C",99,"PZA")]);var ambiguous=Assert.Single(rows,x=>x.Status==LineItemMatchStatus.AMBIGUOUS);Assert.Null(ambiguous.RightLineItemId);}

  [Fact] public void Thirty_products_are_matched_by_identifier_when_order_is_reversed(){var invoice=Enumerable.Range(1,30).Select(x=>Item(x,$"SKU-{x:000}",$"PRODUCT {x}",x,"PZA")).ToArray();var cove=invoice.Reverse().Select((x,i)=>Item(i+1,x.PartNumber!,x.Description!,x.Quantity!.Value,x.Unit!)).ToArray();var rows=new InvoiceCoveLineMatcher().Match(invoice,cove);Assert.Equal(30,rows.Count);Assert.All(rows,x=>Assert.Equal(LineItemMatchStatus.MATCHED,x.Status));}

  [Fact] public async Task V2_reports_quantity_difference_and_routes_exclusive_fields_to_no_aplica(){
    await using var f=await Fixture.Create();
    var invoice=await f.Document("COMMERCIAL_INVOICE","INV-100",[Item(1,"PART-1","PRODUCT",10,"PZA",2,20)]);
    var cove=await f.Document("COVE_ACK","INV-100",[Item(9,"PART-1","PRODUCT",9,"PZA",2,18)]);
    f.Db.DocumentFields.AddRange(Field(invoice.Id,DocumentFieldCodes.PoNumber,"PO-1"),Field(cove.Id,DocumentFieldCodes.CoveId,"COVE-1"));await f.Db.SaveChangesAsync();
    var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));
    Assert.Equal(InvoiceCovePairingStatus.CONFIRMED,result.PairingStatus);
    Assert.True(result.Outcome==ReconciliationOutcome.WITH_DIFFERENCES,$"Outcome={result.Outcome}; mismatches={result.MismatchCount}; insufficient={result.InsufficientEvidenceCount}; lineMatches={result.LineItemsMatched}; statuses={string.Join(',',result.LineItemMatches.Select(x=>x.Status))}; fields={string.Join(';',result.FieldResults.Select(x=>$"{x.DisplayName}:{x.LeftNormalizedValue}/{x.RightNormalizedValue}:{x.FunctionalOutcome}"))}");
    Assert.Contains(result.FieldResults,x=>x.DisplayName=="Cantidad"&&x.FunctionalOutcome==ReconciliationFunctionalOutcome.NO_COINCIDE);
    Assert.All(result.FieldResults.Where(x=>x.Treatment==ReconciliationFieldTreatment.DEFER_TO_OTHER_DOCUMENT),x=>Assert.Equal(ReconciliationFunctionalOutcome.NO_APLICA,x.FunctionalOutcome));
    Assert.DoesNotContain(result.FieldResults,x=>x.FunctionalOutcome.ToString()=="EVIDENCIA_INSUFICIENTE");Assert.Contains("QUANTITY * UNIT_PRICE = LINE_TOTAL",result.CalculationJson);
  }

  [Fact] public async Task V2_uses_one_visible_no_verificable_state_with_reason_code(){await using var f=await Fixture.Create();await f.Document("COMMERCIAL_INVOICE","INV-200",[Item(1,"PART-2","PRODUCT",1,"PZA")]);await f.Document("COVE_ACK","INV-200",[Item(1,"PART-2","PRODUCT",1,"PZA")]);var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));var row=Assert.Single(result.FieldResults,x=>x.DisplayName=="Moneda");Assert.Equal(ReconciliationFunctionalOutcome.NO_VERIFICABLE,row.FunctionalOutcome);Assert.Equal("INSUFFICIENT_EVIDENCE",row.ReasonCode);}

  [Fact] public async Task Quantity_and_unit_are_joint_and_missing_conversion_factor_is_not_a_mismatch(){await using var f=await Fixture.Create();await f.Document("COMMERCIAL_INVOICE","INV-UNIT",[Item(1,"PART-U","PRODUCT",10,"BOX")]);await f.Document("COVE_ACK","INV-UNIT",[Item(2,"PART-U","PRODUCT",500,"PZA")]);var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));var quantity=Assert.Single(result.FieldResults,x=>x.DisplayName=="Cantidad");var unit=Assert.Single(result.FieldResults,x=>x.DisplayName=="Unidad");Assert.Equal(ReconciliationFunctionalOutcome.NO_VERIFICABLE,quantity.FunctionalOutcome);Assert.Equal("CONVERSION_FACTOR_MISSING",quantity.ReasonCode);Assert.Equal(ReconciliationFunctionalOutcome.NO_VERIFICABLE,unit.FunctionalOutcome);}

  [Fact] public async Task Incompatible_units_make_quantity_non_matching_even_when_numbers_match(){await using var f=await Fixture.Create();await f.Document("COMMERCIAL_INVOICE","INV-UNIT-2",[Item(1,"PART-U2","PRODUCT",500,"PAR")]);await f.Document("COVE_ACK","INV-UNIT-2",[Item(2,"PART-U2","PRODUCT",500,"PZA")]);var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));Assert.Equal(ReconciliationFunctionalOutcome.NO_COINCIDE,Assert.Single(result.FieldResults,x=>x.DisplayName=="Cantidad").FunctionalOutcome);Assert.Equal(ReconciliationFunctionalOutcome.NO_COINCIDE,Assert.Single(result.FieldResults,x=>x.DisplayName=="Unidad").FunctionalOutcome);}

  [Fact] public async Task Missing_identified_invoice_product_is_reported_as_falta_en_cove_without_global_ambiguity(){await using var f=await Fixture.Create();await f.Document("COMMERCIAL_INVOICE","INV-MISSING",[Item(1,"PART-A","A",1,"PZA"),Item(2,"PART-B","B",1,"PZA")]);await f.Document("COVE_ACK","INV-MISSING",[Item(8,"PART-A","A",1,"PZA")]);var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));var missing=Assert.Single(result.FieldResults,x=>x.LeftRawValue=="PART-B");Assert.Equal(ReconciliationFunctionalOutcome.FALTA_EN_COVE,missing.FunctionalOutcome);Assert.Equal(ReconciliationOutcome.WITH_DIFFERENCES,result.Outcome);}

  [Fact] public async Task V2_migration_is_incremental_and_down_removes_only_v2_columns(){
    const string previous="20261113020737_DocumentIntelligenceLayerV1";var directory=Path.Combine(Path.GetTempPath(),$"sace-invoice-cove-v2-{Guid.NewGuid():N}");Directory.CreateDirectory(directory);var path=Path.Combine(directory,"migration.db");
    try{await using var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite($"Data Source={path}").Options);var migrator=db.Database.GetService<IMigrator>();await migrator.MigrateAsync(previous);Assert.False(await Column(db,"DocumentReconciliationResults","PairingStatus"));Assert.True(await Table(db,"DocumentReconciliationResults"));await migrator.MigrateAsync();Assert.True(await Column(db,"DocumentReconciliationResults","PairingStatus"));Assert.True(await Column(db,"DocumentReconciliationFieldResults","FunctionalOutcome"));Assert.True(await Column(db,"DocumentLineItems","Brand"));await migrator.MigrateAsync(previous);Assert.False(await Column(db,"DocumentReconciliationResults","PairingStatus"));Assert.False(await Column(db,"DocumentLineItems","Brand"));Assert.True(await Table(db,"DocumentReconciliationResults"));Assert.True(await Table(db,"DocumentFields"));}
    finally{SqliteConnection.ClearAllPools();if(Directory.Exists(directory)&&Path.GetFullPath(directory).StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase))Directory.Delete(directory,true);}
  }

  [Fact] public async Task Http_e2e_returns_confirmed_pair_quantity_difference_calculations_and_exclusive_no_aplica(){
    using var rootFactory=new SaceFactory();using var factory=rootFactory.WithWebHostBuilder(builder=>builder.ConfigureServices(services=>{services.AddScoped<IFileStorageService,HttpSyntheticStorage>();services.AddScoped<IPdfTextExtractor,HttpSyntheticPdfText>();}));var client=factory.CreateClient();
    using(var loginResponse=await client.PostAsJsonAsync("/api/auth/login",new{email="admin@sace.local",password="Admin123!"})){var login=JsonDocument.Parse(await loginResponse.Content.ReadAsStringAsync());loginResponse.EnsureSuccessStatusCode();client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",login.RootElement.GetProperty("token").GetString());}
    Guid operationId;
    await using(var scope=factory.Services.CreateAsyncScope()){
      var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var user=await db.Users.FirstAsync();var operation=new TradeOperation{Folio=$"HTTP-V2-{Guid.NewGuid():N}",PedimentoNumber="26 48 1234 6888002",Period="2026-11",OperationDate=new(2026,11,16),TariffFraction="40169304"};db.Add(operation);await db.SaveChangesAsync();operationId=operation.Id;
      var invoiceType=await db.DocumentTypes.SingleAsync(x=>x.Code=="COMMERCIAL_INVOICE");var coveType=await db.DocumentTypes.SingleAsync(x=>x.Code=="COVE_ACK");
      var invoice=HttpDoc(operation,invoiceType,user.Id,"invoice-v2.pdf","INV-HTTP-V2",Item(1,"HTTP-PART","PRODUCT",10,"PZA",2,20));var cove=HttpDoc(operation,coveType,user.Id,"cove-v2.pdf","INV-HTTP-V2",Item(8,"HTTP-PART","PRODUCT",9,"PZA",2,18));invoice.Fields.Add(Field(invoice.Id,DocumentFieldCodes.PoNumber,"PO-HTTP"));cove.Fields.Add(Field(cove.Id,DocumentFieldCodes.CoveId,"COVE-HTTP"));db.AddRange(invoice,cove);await db.SaveChangesAsync();Assert.Equal(4,await db.DocumentFields.CountAsync(x=>x.OperationDocument.TradeOperationId==operationId));Assert.Equal(2,await db.DocumentLineItems.CountAsync(x=>x.OperationDocument.TradeOperationId==operationId));
    }
    using(var run=await client.PostAsync($"/api/operations/{operationId}/reconciliations/run",null))run.EnsureSuccessStatusCode();
    using var summaryResponse=await client.GetAsync($"/api/operations/{operationId}/reconciliations?page=1&pageSize=100");var summary=JsonDocument.Parse(await summaryResponse.Content.ReadAsStringAsync());summaryResponse.EnsureSuccessStatusCode();var row=summary.RootElement.GetProperty("items").EnumerateArray().First(x=>x.GetProperty("profileCode").GetString()=="RECON-INV-COVE-V2");Assert.True(row.GetProperty("pairingStatus").GetString()=="CONFIRMED",row.GetRawText());
    using var detailResponse=await client.GetAsync($"/api/operations/{operationId}/reconciliations/{row.GetProperty("id").GetGuid()}");var detail=JsonDocument.Parse(await detailResponse.Content.ReadAsStringAsync());detailResponse.EnsureSuccessStatusCode();Assert.Contains(detail.RootElement.GetProperty("fields").EnumerateArray(),x=>x.GetProperty("displayName").GetString()=="Cantidad"&&x.GetProperty("functionalOutcome").GetString()=="NO_COINCIDE");Assert.Contains(detail.RootElement.GetProperty("fields").EnumerateArray(),x=>x.GetProperty("treatment").GetString()=="DEFER_TO_OTHER_DOCUMENT"&&x.GetProperty("functionalOutcome").GetString()=="NO_APLICA");Assert.Contains("QUANTITY * UNIT_PRICE = LINE_TOTAL",detail.RootElement.GetProperty("calculationJson").GetString());
  }

  private static OperationDocument Doc(string type,string? invoice=null){var doc=new OperationDocument{Id=Guid.NewGuid(),DocumentType=new DocumentType{Code=type,Name=type}};if(invoice is not null)doc.Fields.Add(Field(doc.Id,DocumentFieldCodes.InvoiceNumber,invoice));return doc;}
  private static DocumentField Field(Guid documentId,string code,string value)=>new(){OperationDocumentId=documentId,FieldCode=code,CanonicalFieldCode=code,RawValue=value,NormalizedValue=value.Trim().ToUpperInvariant(),ExtractionMethod=ExtractionMethod.PDF_TEXT,DataType=DocumentFieldDataType.TEXT};
  private static DocumentLineItem Item(int sequence,string? part,string description,decimal quantity,string unit,decimal? price=null,decimal? total=null)=>new(){Id=Guid.NewGuid(),Sequence=sequence,PartNumber=part,Description=description,Quantity=quantity,Unit=unit,UnitValue=price,TotalValue=total,Currency=price.HasValue?"USD":null,RawLocator=$"row-{sequence}"};
  private static OperationDocument HttpDoc(TradeOperation operation,DocumentType type,Guid userId,string name,string invoice,DocumentLineItem item){var doc=new OperationDocument{TradeOperation=operation,DocumentType=type,OriginalFileName=name,StoredFileName=name,FilePath=name,Extension=".pdf",MimeType="application/pdf",FileSize=1,UploadedBy=userId,ValidationStatus=ValidationStatus.Valid,IntelligenceStatus=DocumentIntelligenceStatus.COMPLETED};doc.Fields.Add(Field(doc.Id,DocumentFieldCodes.InvoiceNumber,invoice));item.OperationDocument=doc;doc.LineItems.Add(item);return doc;}

  private sealed class HttpSyntheticStorage:IFileStorageService {
    public Task<(string storedName,string relativePath)>SaveAsync(Guid operationId,string documentCode,Microsoft.AspNetCore.Http.IFormFile file,CancellationToken ct)=>throw new NotSupportedException();
    public Task<Stream?>OpenAsync(string path,CancellationToken ct){var invoice=path.Contains("invoice",StringComparison.OrdinalIgnoreCase);var text=invoice?"Invoice: INV-HTTP-V2\nITEM 1\nPART NUMBER: HTTP-PART\nDESCRIPTION: PRODUCT\nQUANTITY: 10 PZA\nUNIT: PZA\nUNIT PRICE: 2\nTOTAL: 20 USD\nCURRENCY: USD":"Reference: INV-HTTP-V2\nITEM 8\nPART NUMBER: HTTP-PART\nDESCRIPTION: PRODUCT\nQUANTITY: 9 PZA\nUNIT: PZA\nUNIT PRICE: 2\nTOTAL: 18 USD\nCURRENCY: USD";return Task.FromResult<Stream?>(new MemoryStream(Encoding.UTF8.GetBytes(text)));}
  }
  private sealed class HttpSyntheticPdfText:IPdfTextExtractor { public async Task<string>ExtractAsync(Stream stream,CancellationToken ct){using var reader=new StreamReader(stream,Encoding.UTF8,leaveOpen:true);return await reader.ReadToEndAsync(ct);} }
  private static async Task<bool>Table(SaceDbContext db,string table)=>await SchemaCount(db,"SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=$name",table)>0;
  private static async Task<bool>Column(SaceDbContext db,string table,string column){var connection=(SqliteConnection)db.Database.GetDbConnection();if(connection.State!=ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=$"PRAGMA table_info([{table}])";await using var reader=await command.ExecuteReaderAsync();while(await reader.ReadAsync())if(string.Equals(reader.GetString(1),column,StringComparison.OrdinalIgnoreCase))return true;return false;}
  private static async Task<long>SchemaCount(SaceDbContext db,string sql,string name){var connection=(SqliteConnection)db.Database.GetDbConnection();if(connection.State!=ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=sql;command.Parameters.AddWithValue("$name",name);return Convert.ToInt64(await command.ExecuteScalarAsync());}

  private sealed class Fixture(SqliteConnection connection,SaceDbContext db,User user,TradeOperation operation):IAsyncDisposable {
    public SaceDbContext Db=>db;public User User=>user;public TradeOperation Operation=>operation;public DocumentReconciliationService Service{get;}=new(db,new DocumentLineItemMatcher(),new InvoiceCovePairingService(),new InvoiceCoveLineMatcher());
    public static async Task<Fixture>Create(){var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="V2",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var operation=new TradeOperation{Folio=$"V2-{Guid.NewGuid():N}",PedimentoNumber="26",Period="2026-11",OperationDate=new(2026,11,16),TariffFraction="40169304"};var profile=new DocumentReconciliationProfile{Code="RECON-INV-COVE-V2",Version=2,Name="V2",LeftDocumentTypeCode="COMMERCIAL_INVOICE",RightDocumentTypeCode="COVE_ACK",Status=ReconciliationProfileStatus.ACTIVE,Fields=[P("Número de factura",DocumentFieldCodes.InvoiceNumber,CrossComparisonType.NORMALIZED_IDENTIFIER),L("Número de parte",DocumentFieldCodes.PartNumber,CrossComparisonType.NORMALIZED_IDENTIFIER),L("Cantidad",DocumentFieldCodes.Quantity,CrossComparisonType.EXACT_NUMERIC),L("Unidad",DocumentFieldCodes.Unit,CrossComparisonType.NORMALIZED_IDENTIFIER),L("Moneda",DocumentFieldCodes.Currency,CrossComparisonType.NORMALIZED_IDENTIFIER),I("Orden de compra",DocumentFieldCodes.PoNumber,true),I("Identificador COVE",DocumentFieldCodes.CoveId,false)]};for(var i=0;i<profile.Fields.Count;i++)profile.Fields[i].Sequence=i+1;db.AddRange(user,operation,profile);await db.SaveChangesAsync();return new(connection,db,user,operation);}
    public async Task<OperationDocument>Document(string type,string invoice,DocumentLineItem[] items){var documentType=await db.DocumentTypes.SingleOrDefaultAsync(x=>x.Code==type)??new DocumentType{Code=type,Name=type};var document=new OperationDocument{TradeOperation=operation,DocumentType=documentType,OriginalFileName=$"{type}-{invoice}.pdf",StoredFileName="x.pdf",FilePath="x",Extension=".pdf",MimeType="application/pdf",FileSize=1,UploadedBy=user.Id,ValidationStatus=ValidationStatus.Valid,IntelligenceStatus=DocumentIntelligenceStatus.COMPLETED};document.Fields.Add(Field(document.Id,DocumentFieldCodes.InvoiceNumber,invoice));foreach(var item in items){item.OperationDocument=document;document.LineItems.Add(item);}db.Add(document);await db.SaveChangesAsync();return document;}
    public async ValueTask DisposeAsync(){await db.DisposeAsync();await connection.DisposeAsync();}
    private static DocumentReconciliationProfileField P(string name,string field,CrossComparisonType comparison)=>new(){DisplayName=name,Section=ReconciliationSection.IDENTIFICATION,LeftFieldCode=field,RightFieldCode=field,ComparisonType=comparison,Treatment=ReconciliationFieldTreatment.DIRECT_COMPARE,ExpectedInLeft=true,ExpectedInRight=true,RequiredForCoverage=true};
    private static DocumentReconciliationProfileField L(string name,string field,CrossComparisonType comparison){var row=P(name,field,comparison);row.LineItemScope=LineItemScope.LINE_ITEM;row.Section=field is DocumentFieldCodes.Quantity or DocumentFieldCodes.Unit?ReconciliationSection.QUANTITIES:ReconciliationSection.VALUES;return row;}
    private static DocumentReconciliationProfileField I(string name,string field,bool invoice)=>new(){DisplayName=name,Section=ReconciliationSection.OTHER,LeftFieldCode=field,RightFieldCode=field,ComparisonType=CrossComparisonType.PRESENCE,Treatment=ReconciliationFieldTreatment.DEFER_TO_OTHER_DOCUMENT,ExpectedInLeft=invoice,ExpectedInRight=!invoice,DeferredValidationTarget="OTHER_DOCUMENT",RequiredForCoverage=false};
  }
}
